export type ParsedSeedMarketInsuranceV3Instruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    reserveAuthority: TAccountMetas[0];
    donor: TAccountMetas[1];
    venue: TAccountMetas[2];
    custody: TAccountMetas[3];
    safety: TAccountMetas[4];
    btcLedger: TAccountMetas[5];
    ethLedger: TAccountMetas[6];
    quoteMint: TAccountMetas[7];
    vault: TAccountMetas[8];
    donorToken: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    eventAuthority: TAccountMetas[11];
    program: TAccountMetas[12];
  };
  data: SeedMarketInsuranceV3InstructionData;
};

export function parseSeedMarketInsuranceV3Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSeedMarketInsuranceV3Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      reserveAuthority: getNextAccount(),
      donor: getNextAccount(),
      venue: getNextAccount(),
      custody: getNextAccount(),
      safety: getNextAccount(),
      btcLedger: getNextAccount(),
      ethLedger: getNextAccount(),
      quoteMint: getNextAccount(),
      vault: getNextAccount(),
      donorToken: getNextAccount(),
      tokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getSeedMarketInsuranceV3InstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
